CREATE OR ALTER PROCEDURE [dbo].[uspProductionOutput_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @DishId UNIQUEIDENTIFIER = NULL
	, @UnitId UNIQUEIDENTIFIER = NULL
	, @ProducedQuantity DECIMAL(18,4) = NULL
	, @AcceptedQuantity DECIMAL(18,4) = NULL
	, @RejectedQuantity DECIMAL(18,4) = NULL
	, @QualityStatus NVARCHAR(MAX) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionBatchId]
			, t.[WasteQty]
			, t.[Remark]
			, t.[DishId]
			, t.[ProducedQuantity]
			, t.[AcceptedQuantity]
			, t.[RejectedQuantity]
			, t.[UnitId]
			, t.[QualityStatus]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[ProductionOutput] AS t
		
		WHERE 1 = 1
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (@DishId IS NULL OR t.[DishId] = @DishId)
			AND (@UnitId IS NULL OR t.[UnitId] = @UnitId)
			AND (@ProducedQuantity IS NULL OR t.[ProducedQuantity] = @ProducedQuantity)
			AND (@AcceptedQuantity IS NULL OR t.[AcceptedQuantity] = @AcceptedQuantity)
			AND (@RejectedQuantity IS NULL OR t.[RejectedQuantity] = @RejectedQuantity)
			AND (ISNULL(@QualityStatus, '') = '' OR t.[QualityStatus] LIKE CONCAT('%', @QualityStatus, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'wasteQty' THEN r.[WasteQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'wasteQty' THEN r.[WasteQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishId' THEN r.[DishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishId' THEN r.[DishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'producedQuantity' THEN r.[ProducedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'producedQuantity' THEN r.[ProducedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitId' THEN r.[UnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitId' THEN r.[UnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
